package com.cryptoloan.loan.domain;import static org.junit.jupiter.api.Assertions.*;import com.cryptoloan.loan.domain.model.*;import java.math.BigDecimal;import java.util.UUID;import org.junit.jupiter.api.Test;class LoanTest{@Test void approvalCreatesApprovedState(){Loan loan=Loan.create(UUID.randomUUID(),"u@example.com","User",new BigDecimal("1000"),"bitcoin",new BigDecimal("0.1"),new BigDecimal("1.20"));Loan approved=loan.approve("abc");assertEquals(LoanStatus.APPROVED,approved.status());assertNotNull(approved.approvedAt());}@Test void warningCanBeClearedAfterRecovery(){Loan loan=Loan.create(UUID.randomUUID(),"u@example.com","User",BigDecimal.TEN,"bitcoin",BigDecimal.ONE,new BigDecimal("1.2")).warn(new BigDecimal("1.3"));assertFalse(loan.observeHealthy(new BigDecimal("1.5")).warningSent());}}

